// HasRequest applies the HasEdge predicate on the "request" edge.
func HasRequest() predicate.RequestAuditAttempt {
	return predicate.RequestAuditAttempt(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, RequestTable, RequestColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRequestWith applies the HasEdge predicate on the "request" edge with a given conditions (other predicates).
func HasRequestWith(preds ...predicate.RequestAuditLog) predicate.RequestAuditAttempt {
	return predicate.RequestAuditAttempt(func(s *sql.Selector) {
		step := newRequestStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RequestAuditAttempt) predicate.RequestAuditAttempt {
	return predicate.RequestAuditAttempt(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RequestAuditAttempt) predicate.RequestAuditAttempt {
	return predicate.RequestAuditAttempt(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RequestAuditAttempt) predicate.RequestAuditAttempt {
	return predicate.RequestAuditAttempt(sql.NotPredicates(p))
}
